"""Fusion 360 script: chip chip4_shell_release_bead_capture_wash_elution (39 x 16 mm), generated by autochip/cad.py from chips/chip4_shell_release_bead_capture_wash_elution.json.
Run it in Fusion: Utilities > Scripts and Add-Ins, or send it through the Fusion MCP execute_code tool
(then set PARTS_DIR first). It
  1. imports every placed part (parts/<module>.stl, mm, chip origin) as its own component,
  2. sketches the board outline, the port circles and every channel centreline ("channel paths"),
  3. sketches every channel as a closed outline at its true width ("channel outlines"), ready to
     extrude-cut 0.3 mm into the fluidic layer (top of the fluidic layer at z = 1.5 mm).
Fusion's API works in cm; the numbers below are mm and converted on the way in.
"""
import adsk.core, adsk.fusion
import os

try:
    PARTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "parts")
except NameError:
    PARTS_DIR = globals()["PARTS_DIR"]
BOARD = [39.0, 16.0]
PARTS = [["release_trap", "trap_chamber"], ["beads_1", "magnetic_chamber"]]
CHANNELS = [["ch_inlet_1_release_trap", 0.5, [[2.0, 8.0], [2.5, 8.0], [4.7, 8.0]]], ["ch_release_trap_beads_1", 0.5, [[18.8421, 8.0], [20.04, 8.0]]], ["ch_beads_1_outlet_1", 0.5, [[34.1821, 8.0], [36.5, 8.0], [37.0, 8.0]]], ["ch_shell_digesting_enzyme_in_release_trap", 0.5, [[11.77, 14.0], [11.77, 13.5], [11.77, 11.5355]]], ["ch_release_trap_release_trap_waste_out", 0.5, [[11.77, 4.4645], [11.77, 2.5], [11.77, 2.0]]], ["ch_magnetic_beads_in_beads_1", 0.5, [[25.11, 14.0], [25.11, 13.5], [25.11, 11.5355]]], ["ch_ethanol_wash_in_beads_1", 0.5, [[29.11, 14.0], [29.11, 13.5], [29.11, 11.5355]]], ["ch_beads_1_beads_1_waste_out", 0.5, [[25.11, 4.4645], [25.11, 2.5], [25.11, 2.0]]], ["ch_elution_buffer_in_beads_1", 0.5, [[29.11, 2.0], [29.11, 2.5], [29.11, 4.4645]]]]
OUTLINES = [["ch_inlet_1_release_trap", [[2.0, 8.25], [4.7, 8.25], [4.7, 7.75], [2.0, 7.75]]], ["ch_release_trap_beads_1", [[18.8421, 8.25], [20.04, 8.25], [20.04, 7.75], [18.8421, 7.75]]], ["ch_beads_1_outlet_1", [[34.1821, 8.25], [37.0, 8.25], [37.0, 7.75], [34.1821, 7.75]]], ["ch_shell_digesting_enzyme_in_release_trap", [[12.02, 14.0], [12.02, 11.5355], [11.52, 11.5355], [11.52, 14.0]]], ["ch_release_trap_release_trap_waste_out", [[12.02, 4.4645], [12.02, 2.0], [11.52, 2.0], [11.52, 4.4645]]], ["ch_magnetic_beads_in_beads_1", [[25.36, 14.0], [25.36, 11.5355], [24.86, 11.5355], [24.86, 14.0]]], ["ch_ethanol_wash_in_beads_1", [[29.36, 14.0], [29.36, 11.5355], [28.86, 11.5355], [28.86, 14.0]]], ["ch_beads_1_beads_1_waste_out", [[25.36, 4.4645], [25.36, 2.0], [24.86, 2.0], [24.86, 4.4645]]], ["ch_elution_buffer_in_beads_1", [[28.86, 2.0], [28.86, 4.4645], [29.36, 4.4645], [29.36, 2.0]]]]
PORTS = [["inlet_1", 2.5, 8.0, 1.0], ["outlet_1", 36.5, 8.0, 1.0], ["shell_digesting_enzyme_in", 11.77, 13.5, 1.0], ["release_trap_waste_out", 11.77, 2.5, 1.0], ["magnetic_beads_in", 25.11, 13.5, 1.0], ["ethanol_wash_in", 29.11, 13.5, 1.0], ["beads_1_waste_out", 25.11, 2.5, 1.0], ["elution_buffer_in", 29.11, 2.5, 1.0]]


def P(xy, z=0.0):
    return adsk.core.Point3D.create(xy[0] / 10.0, xy[1] / 10.0, z / 10.0)


def run(context=None):
    app = adsk.core.Application.get()
    design = adsk.fusion.Design.cast(app.activeProduct)
    root = design.rootComponent
    for module_id, part in PARTS:
        occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
        comp = occ.component
        comp.name = module_id + " (" + part + ")"
        path = os.path.join(PARTS_DIR, module_id + ".stl")
        if design.designType == adsk.fusion.DesignTypes.ParametricDesignType:
            base = comp.features.baseFeatures.add()
            base.startEdit()
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit, base)
            base.finishEdit()
        else:
            comp.meshBodies.add(path, adsk.fusion.MeshUnits.MillimeterMeshUnit)
    sk = root.sketches.add(root.xYConstructionPlane)
    sk.name = "chip4_shell_release_bead_capture_wash_elution outline + ports + channel paths"
    lines = sk.sketchCurves.sketchLines
    lines.addTwoPointRectangle(P((0, 0)), P(BOARD))
    for pid, x, y, d in PORTS:
        sk.sketchCurves.sketchCircles.addByCenterRadius(P((x, y)), d / 20.0)
    for cid, width, pts in CHANNELS:
        for a, b in zip(pts[:-1], pts[1:]):
            lines.addByTwoPoints(P(a), P(b))
    sk2 = root.sketches.add(root.xYConstructionPlane)
    sk2.name = "chip4_shell_release_bead_capture_wash_elution channel outlines (true width)"
    for cid, pts in OUTLINES:
        for a, b in zip(pts, pts[1:] + pts[:1]):
            sk2.sketchCurves.sketchLines.addByTwoPoints(P(a), P(b))
    app.activeViewport.fit()
    return "imported %d parts, sketched %d channels and %d ports" % (len(PARTS), len(CHANNELS), len(PORTS))
